function multicall(bytes[] calldata data) public virtual returns (bytes[] memory results) {
        bytes memory context = msg.sender == _msgSender()
            ? new bytes(0)
            : msg.data[msg.data.length - _contextSuffixLength():];

        results = new bytes[](data.length);
        for (uint256 i = 0; i < data.length; i++) {
            results[i] = Address.functionDelegateCall(address(this), bytes.concat(data[i], context));
        }
        return results;
    }

function openDispute(uint256 option) external accounted {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();

        if (option == 0 || option > ds.numberOfOptions) {
            _revert(IRainPool.InvalidOption.selector);
        }
        if (!ds.optionFinalized[option] || ds.optionWinner[option] == 0) {
            _revert(IRainPool.PoolNotClosed.selector);
        }
        if (ds.optionEndTime[option] + ds.DISPUTE_WINDOW < block.timestamp) {
            _revert(IRainPool.DisputeWindowEnded.selector);
        }

        if (ds.optionState[option] == Types.PoolState.NotDisputed) {
            ds.optionState[option] = Types.PoolState.Disputed;
            ds.isOptionDisputed[option] = true;
        } else if (ds.optionState[option] == Types.PoolState.Disputed && ds.optionWinner[option] != 0) {
            ds.optionState[option] = Types.PoolState.Appealed;
            ds.isOptionAppealed[option] = true;
        } else {
            _revert(IRainPool.DisputeAlreadyOpened.selector);
        }

        if (ds.optionState[option] == Types.PoolState.Disputed) {
            ds.optionDispute[option].disputeFee = _calculateDisputeFee(option, ds.DISPUTE_FEE_MAX, ds.DISPUTE_FEE_MIN);

            IERC20(ds.baseToken).safeTransferFrom(msg.sender, address(this), ds.optionDispute[option].disputeFee);

            ds.optionDispute[option].resolver = LibDiamond.baseResolver(ds);
            ds.optionResolver[option] = LibDiamond.liveDisputeResolver(ds);

            emit IRainPool.OpenDispute({
                caller: msg.sender,
                option: option,
                currentWinner: ds.optionWinner[option],
                disputeFee: ds.optionDispute[option].disputeFee
            });

            ds.optionDispute[option].disputedWinner = ds.optionWinner[option];
            ds.optionDispute[option].disputer = msg.sender;
            ds.optionWinner[option] = 0;
            ds.optionResolved[option] = false;
        } else if (ds.optionState[option] == Types.PoolState.Appealed) {
            ds.optionAppeal[option].disputeFee = _calculateDisputeFee(option, ds.DISPUTE_FEE_MAX, ds.APPEAL_FEE_MIN);
            uint256 oracleCost = _calculateAppealOracleCost();

            IERC20(ds.baseToken).safeTransferFrom(
                msg.sender,
                address(this),
                ds.optionAppeal[option].disputeFee + oracleCost
            );

            ds.optionAppeal[option].resolver = LibDiamond.liveDisputeResolver(ds);

            // The oracle is funded ONLY by the appealer's oracle-cost component, collected above
            // on top of their stake. optionResolverShare is never touched: it is reward money,
            // paid at settlement to whichever resolver's answer matches the final winner
            // (ClaimFacet). Funding the oracle from it — as this used to — coupled oracle budget
            // to trading volume and deadlocked appeals on options that never traded.
            uint256 resolverShare;

            if (ds.baseToken != ds.usdt) {
                resolverShare = LibUtils.swapTokensForUSDT(ds.baseToken, oracleCost, ds.tokenData);
            } else {
                resolverShare = oracleCost;
            }
            // ds.oracleFixedFee is retired and 0 on every pool from a live deployer, so in
            // practice the oracle is funded by resolverShare alone. It is no longer prepaid at
            // pool creation — a non-zero value would be pulled straight from collateral here.
            IERC20(ds.usdt).forceApprove(ds.FACTORY, resolverShare + ds.oracleFixedFee);

            ds.optionResolver[option] = IRainDeployer(ds.FACTORY).createOracle(
                _calculateNumberOfOracles(resolverShare),
                resolverShare,
                ds.oracleFixedFee,
                address(this),
                block.timestamp + ds.oracleEndTime,
                // 3-option answer space: 1 = YES, 2 = NO, 3 = "too early" (option was resolved
                // prematurely; handled by ResolutionFacet.resolveAppealTooEarly).
                3,
                ds.ipfsUri
            );

            emit IRainPool.CreateOracle({
                creatorContract: address(this),
                createdContract: ds.optionResolver[option],
                option: option
            });

            emit IRainPool.ResolverClaim(ds.optionResolver[option], option, resolverShare + ds.oracleFixedFee);

            emit IRainPool.OpenAppeal({
                caller: msg.sender,
                option: option,
                currentWinner: ds.optionWinner[option],
                appealFee: ds.optionAppeal[option].disputeFee
            });

            ds.optionAppeal[option].disputedWinner = ds.optionWinner[option];
            ds.optionAppeal[option].disputer = msg.sender;
            ds.optionWinner[option] = 0;
            ds.optionResolved[option] = false;
        }

        if (ds.optionState[option] != Types.PoolState.NotDisputed) {
            emit IRainPool.ResolverSet({ resolver: ds.optionResolver[option], option: option });
        }
    }

function writeOff(address borrower, address to) external returns (bool writtenOff) {
        accrueInterest();
        // check for write off
        uint debt = getDebtOf(borrower);
        if(debt > 0) {
            uint collateralBalance = collateralBalances[borrower]; // in collateral token decimals
            (uint price,, bool allowLiquidations) = getCollateralPrice();
            require(allowLiquidations, "liquidations disabled");
            uint collateralValue = price * collateralBalance / 1e18;
            // if debt is more than 100 times the collateral value, write off
            if(debt > collateralValue * 100) {
                // 1. delete all of the borrower's debt
                decreaseDebt(borrower, type(uint).max);
                // 2. redistribute excess debt among remaining borrowers
                uint256 totalDebt = totalFreeDebt + totalPaidDebt;
                if (totalDebt > 0) {
                    uint256 freeDebtIncrease = debt * totalFreeDebt / totalDebt;
                    uint256 paidDebtIncrease = debt - freeDebtIncrease;

                    totalFreeDebt += freeDebtIncrease;
                    totalPaidDebt += paidDebtIncrease;
                }

                collateralBalances[borrower] = 0;

                emit WrittenOff(borrower, to, debt, collateralBalance);
                writtenOff = true;

                collateral.safeTransfer(to, collateralBalance);
            }
        }
    }

function rebalance() external override nonReentrant {
        checkCanRebalance();
        if (rebalanceDelegate != address(0)) {
            require(
                msg.sender == manager || msg.sender == rebalanceDelegate,
                "rebalanceDelegate"
            );
        }

        // Withdraw all current liquidity from Uniswap pool
        int24 _fullLower = fullLower;
        int24 _fullUpper = fullUpper;
        {
            (uint128 fullLiquidity, , , , ) = _position(_fullLower, _fullUpper);
            (uint128 baseLiquidity, , , , ) = _position(baseLower, baseUpper);
            (uint128 limitLiquidity, , , , ) = _position(limitLower, limitUpper);
            _burnAndCollect(_fullLower, _fullUpper, fullLiquidity);
            _burnAndCollect(baseLower, baseUpper, baseLiquidity);
            _burnAndCollect(limitLower, limitUpper, limitLiquidity);
        }

        // Calculate new ranges
        (, int24 tick, , , , , ) = pool.slot0();
        int24 tickFloor = _floor(tick);
        int24 tickCeil = tickFloor + tickSpacing;

        int24 _baseLower = tickFloor - baseThreshold;
        int24 _baseUpper = tickCeil + baseThreshold;
        int24 _bidLower = tickFloor - limitThreshold;
        int24 _bidUpper = tickFloor;
        int24 _askLower = tickCeil;
        int24 _askUpper = tickCeil + limitThreshold;

        // Emit snapshot to record balances and supply
        uint256 balance0 = getBalance0();
        uint256 balance1 = getBalance1();
        emit Snapshot(tick, balance0, balance1, totalSupply());

        // Place full range order on Uniswap
        {
            uint128 maxFullLiquidity = _liquidityForAmounts(
                _fullLower,
                _fullUpper,
                balance0,
                balance1
            );
            uint128 fullLiquidity = _toUint128(
                uint256(maxFullLiquidity).mul(fullRangeWeight).div(1e6)
            );
            _mintLiquidity(_fullLower, _fullUpper, fullLiquidity);
        }

        // Place base order on Uniswap
        balance0 = getBalance0();
        balance1 = getBalance1();
        {
            uint128 baseLiquidity = _liquidityForAmounts(
                _baseLower,
                _baseUpper,
                balance0,
                balance1
            );
            _mintLiquidity(_baseLower, _baseUpper, baseLiquidity);
            (baseLower, baseUpper) = (_baseLower, _baseUpper);
        }

        // Place bid or ask order on Uniswap depending on which token is left
        balance0 = getBalance0();
        balance1 = getBalance1();
        uint128 bidLiquidity = _liquidityForAmounts(_bidLower, _bidUpper, balance0, balance1);
        uint128 askLiquidity = _liquidityForAmounts(_askLower, _askUpper, balance0, balance1);
        if (bidLiquidity > askLiquidity) {
            _mintLiquidity(_bidLower, _bidUpper, bidLiquidity);
            (limitLower, limitUpper) = (_bidLower, _bidUpper);
        } else {
            _mintLiquidity(_askLower, _askUpper, askLiquidity);
            (limitLower, limitUpper) = (_askLower, _askUpper);
        }

        lastTimestamp = block.timestamp;
        lastTick = tick;

        // Update fee only at each rebalance, so that if fee is increased
        // it won't be applied retroactively to current open positions
        protocolFee = factory.protocolFee();
        managerFee = pendingManagerFee;
    }

function repay(uint256 amount, address receiver) public virtual nonReentrant returns (uint256) {
        (VaultCache memory vaultCache, address account) = initOperation(OP_REPAY, CHECKACCOUNT_NONE);

        uint256 owed = getCurrentOwed(vaultCache, receiver).toAssetsUp().toUint();

        Assets assets = (amount == type(uint256).max ? owed : amount).toAssets();
        if (assets.isZero()) return 0;

        pullAssets(vaultCache, account, assets);

        decreaseBorrow(vaultCache, receiver, assets);

        return assets.toUint();
    }

function repayWithShares(uint256 amount, address receiver) public virtual nonReentrant returns (uint256, uint256) {
        (VaultCache memory vaultCache, address account) = initOperation(OP_REPAY_WITH_SHARES, CHECKACCOUNT_CALLER);

        Assets owed = getCurrentOwed(vaultCache, receiver).toAssetsUp();
        if (owed.isZero()) return (0, 0);

        Assets assets;
        Shares shares;

        if (amount == type(uint256).max) {
            shares = vaultStorage.users[account].getBalance();
            assets = shares.toAssetsDown(vaultCache);
        } else {
            assets = amount.toAssets();
            shares = assets.toSharesUp(vaultCache);
        }

        if (assets.isZero()) return (0, 0);

        if (assets > owed) {
            assets = owed;
            shares = assets.toSharesUp(vaultCache);
        }

        // Burn ETokens
        decreaseBalance(vaultCache, account, account, account, shares, assets);

        // Burn DTokens
        decreaseBorrow(vaultCache, receiver, assets);

        return (shares.toUint(), assets.toUint());
    }

function liquidate(address violator, address collateral, uint256 repayAssets, uint256 minYieldBalance)
        public
        virtual
        nonReentrant
    {
        (VaultCache memory vaultCache, address liquidator) = initOperation(OP_LIQUIDATE, CHECKACCOUNT_CALLER);

        LiquidationCache memory liqCache =
            calculateLiquidation(vaultCache, liquidator, violator, collateral, repayAssets);

        executeLiquidation(vaultCache, liqCache, minYieldBalance);
    }

function liquidate(address violator, address /*collateral*/, uint /*repayAssets*/, uint /*minYieldBalance*/) external view {
        require(collateralVaultFactory.isCollateralVault(violator), ViolatorNotCollateralVault());
        // Allow EVK debt socialization when collateral vault doesn't have assets
        require(CollateralVaultBase(violator).totalAssetsDepositedOrReserved() == 0, NotExternallyLiquidated());
    }

function liquidate() external callThroughEVC nonReentrant {
        createVaultSnapshot();
        require(_isNotExternallyLiquidated(), ExternallyLiquidated());

        address liquidator = _msgSender();
        address prevBorrower = borrower;
        require(liquidator != prevBorrower, SelfLiquidation());
        require(_canLiquidate(), HealthyNotLiquidatable());
        require(liquidatedBorrower == address(0), AlreadyLiquidated());

        (uint B, uint C) = _getBC();

        collateralForLiquidatedBorrower = collateralForBorrower(B, C);
        liquidatedBorrower = prevBorrower;

        // liquidator takes over this vault from the current borrower
        borrower = liquidator;

        collateralVaultFactory.setCollateralVaultLiquidated(liquidator);

        evc.requireAccountAndVaultStatusCheck(address(this));
    }

function repay(uint _amount) external onlyBorrowerAndNotExtLiquidated nonReentrant {
        createVaultSnapshot();
        uint _maxRepay = maxRepay();
        if (_amount == type(uint).max) {
            _amount = _maxRepay;
        } else {
            require(_amount <= _maxRepay, RepayingMoreThanMax());
        }

        _repay(_amount);
        _handleExcessCredit(_invariantCollateralAmount());
        evc.requireVaultStatusCheck();
        emit T_Repay(_amount);
    }

function liquidateBorrow(address borrower, uint repayAmount, IPToken cTokenCollateral) external override returns (uint) {
        (uint err,) = liquidateBorrowInternal(borrower, repayAmount, cTokenCollateral);
        return err;
    }

function mintForMigrate(uint mintAmount, uint mintTokens) external returns (uint) {
        (uint err,) = mintInternalForMigrate(mintAmount, mintTokens);
        return err;
    }

function sellRepoToken(
        address repoToken,
        uint256 repoTokenAmount
    ) external whenNotPaused notBlacklisted(repoToken) {
        // Ensure the amount of repoTokens to sell is greater than zero
        require(repoTokenAmount > 0);

        // Make sure repo token is valid and deployed by Term
        if (!_isTermDeployed(repoToken)) {
            revert RepoTokenList.InvalidRepoToken(repoToken);
        }

        // Validate and insert the repoToken into the list, retrieve auction rate and redemption timestamp
        (bool isRepoTokenValid, uint256 redemptionTimestamp) = repoTokenListData
            .validateAndInsertRepoToken(
                ITermRepoToken(repoToken),
                strategyState.discountRateAdapter,
                address(asset)
            );

        if (!isRepoTokenValid) {
            revert RepoTokenList.InvalidRepoToken(repoToken);
        }

        // Sweep assets and redeem repoTokens, if needed
        _redeemRepoTokens(0);

        // Retrieve total asset value and liquid balance and ensure they are greater than zero
        uint256 liquidBalance = _totalLiquidBalance();
        require(liquidBalance > 0);
        uint256 totalAssetValue = _totalAssetValue(liquidBalance);
        require(totalAssetValue > 0);

        uint256 discountRate = strategyState
            .discountRateAdapter
            .getDiscountRate(repoToken);

        // Calculate the repoToken amount in base asset precision
        uint256 repoTokenAmountInBaseAssetPrecision = RepoTokenUtils
            .getNormalizedRepoTokenAmount(
                repoToken,
                repoTokenAmount,
                PURCHASE_TOKEN_PRECISION,
                strategyState.discountRateAdapter.repoRedemptionHaircut(
                    repoToken
                )
            );

        // Calculate the proceeds from selling the repoToken
        uint256 proceeds = RepoTokenUtils.calculatePresentValue(
            repoTokenAmountInBaseAssetPrecision,
            PURCHASE_TOKEN_PRECISION,
            redemptionTimestamp,
            discountRate + strategyState.discountRateMarkup
        );

        // Ensure the liquid balance is sufficient to cover the proceeds
        if (liquidBalance < proceeds) {
            revert InsufficientLiquidBalance(liquidBalance, proceeds);
        }

        // Calculate resulting time to maturity after the sale and ensure it doesn't exceed the threshold
        uint256 resultingTimeToMaturity = _calculateWeightedMaturity(
            repoToken,
            repoTokenAmount,
            liquidBalance - proceeds
        );
        if (resultingTimeToMaturity > strategyState.timeToMaturityThreshold) {
            revert TimeToMaturityAboveThreshold();
        }

        // Ensure the remaining liquid balance is above the liquidity threshold
        uint256 newLiquidReserveRatio = ((liquidBalance - proceeds) * 1e18) /
            totalAssetValue; // NOTE: we require totalAssetValue > 0 above
        if (newLiquidReserveRatio < strategyState.requiredReserveRatio) {
            revert BalanceBelowRequiredReserveRatio();
        }

        // Validate resulting repoToken concentration to ensure it meets requirements
        _validateRepoTokenConcentration(
            repoToken,
            repoTokenAmountInBaseAssetPrecision,
            totalAssetValue,
            proceeds
        );

        // withdraw from underlying vault
        _withdrawAsset(proceeds);

        // Transfer repoTokens from the sender to the contract
        IERC20(repoToken).safeTransferFrom(
            msg.sender,
            address(this),
            repoTokenAmount
        );

        // Transfer the proceeds in assets to the sender
        IERC20(asset).safeTransfer(msg.sender, proceeds);
    }

function burnToGetOutInLine(uint256 amount)giveYield()fetch(msg.sender) onlyRole(ADMIN_ROLE) external {
        // get in line to exit the protocol
        // burn shares
        _burn(msg.sender,amount);
        // add to size
        mySizeWaitingForExit[msg.sender] += amount;
        inExitLine += amount;
    }

function defaultContract(uint256 _nftID) giveYield() public {
        (uint256 outstanding, uint256 defaultAt,) = openDebt(_nftID); 
        require(outstanding > defaultAt, "not ready to default");
        // burn it down to 0
        stablesInContracts -= baseSize[_nftID];
        coinsInContracts -= coinSize[_nftID];
        baseSize[_nftID] = 0;
        coinSize[_nftID] = 0;
    }

